cat > /work/submit/planb64.cpp <<'CPPEOF'
// PlanB64: offline FIB compiler and longest-prefix-match lookup tool.
//
// The tool reduces IPv6 LPM over prefixes of length 0..64 to predecessor
// search over a canonical set of disjoint intervals (the "image").  The image
// stores the minimal change-point representation of the function
//     upper64(address) -> (NEXT_HOP, PREFIX_LENGTH)
// over the whole 64-bit key space.
//
// All parsing is strict: any malformed input yields exit status 2 and a single
// "ERROR: ..." line on stderr with nothing on stdout.

#include <arpa/inet.h>

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <memory>
#include <queue>
#include <string>
#include <vector>

namespace {

// ---------------------------------------------------------------- limits ----

constexpr std::size_t kMaxFibRecords = 200000;
constexpr std::size_t kMaxTraceRecords = 1000000;
constexpr std::size_t kMaxImageRows = 400001;
constexpr std::size_t kMaxLineBytes = 65536;   // generous safety valve
constexpr std::size_t kReadChunk = 1u << 20;
constexpr std::size_t kWriteChunk = 1u << 20;

constexpr std::uint64_t kMaxHop = 4294967295ull;
constexpr int kMaxPrefixLen = 64;

// Packed (hop, len) value; NO_MATCH is the only reserved encoding.
constexpr std::uint64_t kNoMatch = ~std::uint64_t(0);

inline std::uint64_t packValue(std::uint64_t hop, std::uint64_t len) {
    return (hop << 8) | len;
}

// -------------------------------------------------------------- utilities ---

struct Error {
    std::string msg;
};

[[noreturn]] inline void fail(const std::string& m) { throw Error{m}; }
[[noreturn]] inline void fail(const char* m) { throw Error{m}; }

struct FileCloser {
    void operator()(FILE* f) const noexcept {
        if (f != nullptr) std::fclose(f);
    }
};
using FilePtr = std::unique_ptr<FILE, FileCloser>;

FilePtr openRead(const std::string& path, const char* what) {
    FILE* f = std::fopen(path.c_str(), "rb");
    if (f == nullptr) fail(std::string("cannot open ") + what + " '" + path + "' for reading");
    return FilePtr(f);
}

FilePtr openWrite(const std::string& path, const char* what) {
    FILE* f = std::fopen(path.c_str(), "wb");
    if (f == nullptr) fail(std::string("cannot open ") + what + " '" + path + "' for writing");
    return FilePtr(f);
}

// Buffered line splitter.  Accepted line terminators: '\n'.  A final line
// without a terminator is still returned.  Callers must not retain the
// returned pointer across calls.
class LineReader {
public:
    explicit LineReader(FILE* f) : f_(f), buf_(kReadChunk) {}

    LineReader(const LineReader&) = delete;
    LineReader& operator=(const LineReader&) = delete;

    // Returns false at end of file; otherwise sets s/n to the line contents
    // with the trailing '\n' removed.
    bool next(const char*& s, std::size_t& n) {
        spill_.clear();
        bool spilled = false;
        for (;;) {
            if (pos_ >= len_ && !fill()) {
                if (spilled) {
                    hadNewline_ = false;
                    s = spill_.data();
                    n = spill_.size();
                    return true;
                }
                return false;
            }
            const char* base = buf_.data() + pos_;
            const std::size_t avail = len_ - pos_;
            const char* nl = static_cast<const char*>(std::memchr(base, '\n', avail));
            if (nl != nullptr) {
                const std::size_t cnt = static_cast<std::size_t>(nl - base);
                pos_ += cnt + 1;
                hadNewline_ = true;
                if (spilled) {
                    spill_.append(base, cnt);
                    s = spill_.data();
                    n = spill_.size();
                } else {
                    s = base;
                    n = cnt;
                }
                return true;
            }
            spill_.append(base, avail);
            spilled = true;
            pos_ += avail;
            if (spill_.size() > kMaxLineBytes) fail("input line too long");
        }
    }

    // True when at least one byte was seen and the final line ended with '\n'.
    bool endsWithNewline() const { return sawByte_ && hadNewline_; }

private:
    bool fill() {
        if (eof_) return false;
        const std::size_t got = std::fread(buf_.data(), 1, buf_.size(), f_);
        if (got == 0) {
            eof_ = true;
            return false;
        }
        sawByte_ = true;
        pos_ = 0;
        len_ = got;
        return true;
    }

    FILE* f_;
    std::vector<char> buf_;
    std::size_t pos_ = 0;
    std::size_t len_ = 0;
    bool eof_ = false;
    bool sawByte_ = false;
    bool hadNewline_ = false;
    std::string spill_;
};

inline bool isSpaceChar(char c) { return c == ' ' || c == '\t' || c == '\r'; }
inline bool isDigitChar(char c) { return c >= '0' && c <= '9'; }
inline bool isLowerHexChar(char c) {
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
}

// Splits a record on space/tab/CR.  Rejects any other control character (this
// also rejects embedded NULs, which would otherwise truncate C-string parses).
// Returns the number of tokens, saturating at maxTokens + 1.
std::size_t splitTokens(const char* s, std::size_t n, std::vector<std::pair<const char*, std::size_t>>& out,
                        std::size_t maxTokens) {
    out.clear();
    std::size_t i = 0;
    while (i < n) {
        while (i < n && isSpaceChar(s[i])) ++i;
        if (i >= n) break;
        const std::size_t start = i;
        while (i < n && !isSpaceChar(s[i])) {
            const unsigned char c = static_cast<unsigned char>(s[i]);
            if (c < 0x20u || c == 0x7fu) fail("invalid control character in record");
            ++i;
        }
        if (out.size() < maxTokens) out.emplace_back(s + start, i - start);
        else return maxTokens + 1;
    }
    return out.size();
}

// Decimal digits only (leading zeros allowed), value must stay <= limit.
bool parseDigits(const char* s, std::size_t n, std::uint64_t limit, std::uint64_t& out) {
    if (n == 0) return false;
    std::uint64_t v = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (!isDigitChar(s[i])) return false;
        if (v > limit) return false;
        v = v * 10u + static_cast<std::uint64_t>(s[i] - '0');
    }
    if (v > limit) return false;
    out = v;
    return true;
}

// Canonical image spelling: digits only, no leading zeros.
bool parseUnpaddedDigits(const char* s, std::size_t n, std::uint64_t limit, std::uint64_t& out) {
    if (n == 0) return false;
    if (n > 1 && s[0] == '0') return false;
    return parseDigits(s, n, limit, out);
}

bool parseIPv6(const char* s, std::size_t n, std::uint64_t& upper64) {
    if (n == 0 || n > 46) return false;
    char tmp[48];
    std::memcpy(tmp, s, n);
    tmp[n] = '\0';
    unsigned char bytes[16];
    if (inet_pton(AF_INET6, tmp, bytes) != 1) return false;
    std::uint64_t key = 0;
    for (int i = 0; i < 8; ++i) key = (key << 8) | static_cast<std::uint64_t>(bytes[i]);
    upper64 = key;
    return true;
}

// ----------------------------------------------------------------- build ----

struct Prefix {
    std::uint64_t key;       // normalized upper-64 network address
    std::uint64_t endExcl;   // key + 2^(64-len); 0 means "wraps past 2^64"
    std::uint64_t value;     // packed (hop, len)
    std::uint32_t len;
};

Prefix makePrefix(std::uint64_t key, std::uint32_t len, std::uint64_t hop) {
    Prefix p;
    p.key = (len == 0) ? 0u : (key & (~std::uint64_t(0) << (64 - len)));
    p.len = len;
    p.value = packValue(hop, len);
    p.endExcl = (len == 0) ? 0u : p.key + (std::uint64_t(1) << (64 - len));
    return p;
}

void parseFibLine(const char* s, std::size_t n, Prefix& out) {
    std::vector<std::pair<const char*, std::size_t>> tok;
    tok.reserve(3);
    const std::size_t nt = splitTokens(s, n, tok, 2);
    if (nt != 2) fail("FIB record must have exactly two fields");

    const char* p = tok[0].first;
    const std::size_t pn = tok[0].second;
    const char* slash = static_cast<const char*>(std::memchr(p, '/', pn));
    if (slash == nullptr) fail("FIB record is missing '/' before the prefix length");
    const std::size_t addrLen = static_cast<std::size_t>(slash - p);
    const char* lenStr = slash + 1;
    const std::size_t lenLen = pn - addrLen - 1;

    std::uint64_t addr = 0;
    if (!parseIPv6(p, addrLen, addr)) fail("FIB record has an invalid IPv6 address");

    std::uint64_t len = 0;
    if (!parseDigits(lenStr, lenLen, 128, len)) fail("FIB record has an invalid prefix length");
    if (len > static_cast<std::uint64_t>(kMaxPrefixLen)) fail("unsupported prefix length (only 0..64)");

    std::uint64_t hop = 0;
    if (!parseDigits(tok[1].first, tok[1].second, kMaxHop, hop)) fail("FIB record has an invalid next hop");

    out = makePrefix(addr, static_cast<std::uint32_t>(len), hop);
}

std::vector<Prefix> readFib(const std::string& path) {
    FilePtr fp = openRead(path, "FIB");
    LineReader rd(fp.get());
    std::vector<Prefix> prefixes;
    const char* s = nullptr;
    std::size_t n = 0;
    while (rd.next(s, n)) {
        bool blank = true;
        for (std::size_t i = 0; i < n; ++i) {
            if (!isSpaceChar(s[i])) { blank = false; break; }
        }
        if (blank) continue;
        if (prefixes.size() >= kMaxFibRecords) fail("too many FIB records");
        Prefix p;
        parseFibLine(s, n, p);
        prefixes.push_back(p);
    }
    return prefixes;
}

struct Row {
    std::uint64_t start;
    std::uint64_t value;   // packed (hop,len) or kNoMatch
};

std::vector<Row> compileImage(std::vector<Prefix> prefixes) {
    // Reject duplicates of the same normalized (network, length) pair.
    std::sort(prefixes.begin(), prefixes.end(), [](const Prefix& a, const Prefix& b) {
        if (a.key != b.key) return a.key < b.key;
        return a.len < b.len;
    });
    for (std::size_t i = 1; i < prefixes.size(); ++i) {
        if (prefixes[i].key == prefixes[i - 1].key && prefixes[i].len == prefixes[i - 1].len)
            fail("duplicate normalized prefix in FIB");
    }

    // Change points can only be prefix starts or prefix ends (+1); key 0 is
    // always present because the image covers the whole key space.
    std::vector<std::uint64_t> points;
    points.reserve(prefixes.size() * 2 + 1);
    points.push_back(0);
    for (const Prefix& p : prefixes) {
        points.push_back(p.key);
        if (p.endExcl != 0) points.push_back(p.endExcl);
    }
    std::sort(points.begin(), points.end());
    points.erase(std::unique(points.begin(), points.end()), points.end());
    if (points.size() > kMaxImageRows) fail("compiled image has too many rows");

    // Sweep the change points, keeping the longest active prefix in a max-heap
    // with lazy removal of intervals that already ended.
    struct Cmp {
        bool operator()(const Prefix& a, const Prefix& b) const { return a.len < b.len; }
    };
    std::priority_queue<Prefix, std::vector<Prefix>, Cmp> active;
    std::vector<Row> rows;
    rows.reserve(points.size());
    std::size_t next = 0;
    bool havePrev = false;
    std::uint64_t prev = 0;
    for (const std::uint64_t k : points) {
        while (next < prefixes.size() && prefixes[next].key <= k) active.push(prefixes[next++]);
        while (!active.empty()) {
            const Prefix& top = active.top();
            if (top.endExcl != 0 && top.endExcl <= k) active.pop();
            else break;
        }
        const std::uint64_t value = active.empty() ? kNoMatch : active.top().value;
        if (!havePrev || value != prev) {
            rows.push_back(Row{k, value});
            havePrev = true;
            prev = value;
        }
    }
    if (rows.empty()) rows.push_back(Row{0, kNoMatch});
    if (rows.size() > kMaxImageRows) fail("compiled image has too many rows");
    return rows;
}

// Buffered ASCII writer used for both the image and lookup answers.
class OutBuffer {
public:
    OutBuffer(FILE* f, std::size_t cap) : f_(f), buf_(cap) {}
    OutBuffer(const OutBuffer&) = delete;
    OutBuffer& operator=(const OutBuffer&) = delete;
    ~OutBuffer() { (void)flush(); }

    void push(const char* s, std::size_t n) {
        if (n > buf_.size() - used_) flush();
        if (n > buf_.size()) {
            writeRaw(s, n);
            return;
        }
        std::memcpy(buf_.data() + used_, s, n);
        used_ += n;
    }

    void push(char c) {
        if (used_ == buf_.size()) flush();
        buf_[used_++] = c;
    }

    void flush() {
        if (used_ == 0) return;
        writeRaw(buf_.data(), used_);
        used_ = 0;
    }

    void finish() {
        flush();
        if (std::fflush(f_) != 0) fail("output write failure");
    }

private:
    void writeRaw(const char* s, std::size_t n) {
        std::size_t off = 0;
        while (off < n) {
            const std::size_t w = std::fwrite(s + off, 1, n - off, f_);
            if (w == 0) fail("output write failure");
            off += w;
        }
    }

    FILE* f_;
    std::vector<char> buf_;
    std::size_t used_ = 0;
};

char* writeHex16(char* p, std::uint64_t v) {
    static const char digits[] = "0123456789abcdef";
    for (int i = 15; i >= 0; --i) {
        p[i] = digits[static_cast<int>(v & 0xfu)];
        v >>= 4;
    }
    return p + 16;
}

// Writes an unpadded decimal (or "-1") followed by '\n' where requested.
char* writeUnsigned(char* p, std::uint64_t v) {
    char tmp[24];
    int n = 0;
    do {
        tmp[n++] = static_cast<char>('0' + (v % 10u));
        v /= 10u;
    } while (v != 0);
    while (n--) *p++ = tmp[n];
    return p;
}

void writeImage(const std::string& path, const std::vector<Row>& rows) {
    FilePtr fp = openWrite(path, "image");
    OutBuffer out(fp.get(), kWriteChunk);
    out.push("PLANB64 1\n", 10);
    {
        char line[32];
        char* p = writeUnsigned(line, rows.size());
        *p++ = '\n';
        out.push(line, static_cast<std::size_t>(p - line));
    }
    char line[64];
    for (const Row& r : rows) {
        char* p = writeHex16(line, r.start);
        *p++ = ' ';
        if (r.value == kNoMatch) {
            *p++ = '-'; *p++ = '1'; *p++ = ' '; *p++ = '-'; *p++ = '1';
        } else {
            p = writeUnsigned(p, r.value >> 8);
            *p++ = ' ';
            p = writeUnsigned(p, r.value & 0xffu);
        }
        *p++ = '\n';
        out.push(line, static_cast<std::size_t>(p - line));
    }
    out.finish();
}

void cmdBuild(const std::string& fibPath, const std::string& imagePath) {
    std::vector<Prefix> prefixes = readFib(fibPath);
    std::vector<Row> rows = compileImage(std::move(prefixes));
    // Only touch the destination once the whole FIB has been validated.
    writeImage(imagePath, rows);
}

// ---------------------------------------------------------------- lookup ----

struct Image {
    std::vector<std::uint64_t> keys;
    std::vector<std::uint64_t> values;
};

bool parseRowLine(const char* s, std::size_t n, Row& out) {
    if (n < 16 + 1 + 1 + 1 + 1) return false;
    for (std::size_t i = 0; i < 16; ++i)
        if (!isLowerHexChar(s[i])) return false;
    if (s[16] != ' ') return false;

    std::uint64_t key = 0;
    for (std::size_t i = 0; i < 16; ++i) {
        const char c = s[i];
        unsigned d;
        if (c >= '0' && c <= '9') d = static_cast<unsigned>(c - '0');
        else d = static_cast<unsigned>(c - 'a') + 10u;
        key = (key << 4) | d;
    }

    std::size_t p = 17;
    while (p < n && s[p] != ' ') ++p;
    if (p == n || p == 17) return false;
    const char* hopStr = s + 17;
    const std::size_t hopLen = p - 17;
    const char* lenStr = s + p + 1;
    const std::size_t lenLen = n - p - 1;
    if (lenLen == 0) return false;
    if (std::memchr(lenStr, ' ', lenLen) != nullptr) return false;

    std::uint64_t hop = 0, len = 0;
    const bool hopNeg = (hopLen == 2 && hopStr[0] == '-' && hopStr[1] == '1');
    const bool lenNeg = (lenLen == 2 && lenStr[0] == '-' && lenStr[1] == '1');
    if (hopNeg && lenNeg) {
        out.start = key;
        out.value = kNoMatch;
        return true;
    }
    if (hopNeg || lenNeg) return false;
    if (!parseUnpaddedDigits(hopStr, hopLen, kMaxHop, hop)) return false;
    if (!parseUnpaddedDigits(lenStr, lenLen, static_cast<std::uint64_t>(kMaxPrefixLen), len)) return false;
    out.start = key;
    out.value = packValue(hop, len);
    return true;
}

Image readImage(const std::string& path) {
    FilePtr fp = openRead(path, "image");
    LineReader rd(fp.get());
    const char* s = nullptr;
    std::size_t n = 0;

    if (!rd.next(s, n) || n != 9 || std::memcmp(s, "PLANB64 1", 9) != 0)
        fail("image has a bad header line");

    if (!rd.next(s, n)) fail("image is missing the row count");
    std::uint64_t count = 0;
    if (!parseUnpaddedDigits(s, n, kMaxImageRows, count)) fail("image has a bad row count");
    if (count < 1) fail("image row count must be at least 1");

    Image img;
    img.keys.reserve(static_cast<std::size_t>(count));
    img.values.reserve(static_cast<std::size_t>(count));
    std::uint64_t prevKey = 0;
    std::uint64_t prevValue = 0;
    for (std::uint64_t i = 0; i < count; ++i) {
        if (!rd.next(s, n)) fail("image has fewer rows than its count");
        Row row;
        if (!parseRowLine(s, n, row)) fail("image has a malformed row");
        if (i == 0) {
            if (row.start != 0) fail("image first key must be zero");
        } else {
            if (row.start <= prevKey) fail("image keys must strictly increase");
            if (row.value == prevValue) fail("image has equal adjacent pairs");
        }
        img.keys.push_back(row.start);
        img.values.push_back(row.value);
        prevKey = row.start;
        prevValue = row.value;
    }
    if (rd.next(s, n)) fail("image has extra records after its row count");
    if (!rd.endsWithNewline()) fail("image is missing its final newline");
    return img;
}

std::vector<std::uint64_t> readTrace(const std::string& path) {
    FilePtr fp = openRead(path, "trace");
    LineReader rd(fp.get());
    std::vector<std::uint64_t> keys;
    const char* s = nullptr;
    std::size_t n = 0;
    while (rd.next(s, n)) {
        std::size_t b = 0, e = n;
        while (b < e && isSpaceChar(s[b])) ++b;
        while (e > b && isSpaceChar(s[e - 1])) --e;
        if (b == e) continue;
        if (keys.size() >= kMaxTraceRecords) fail("too many trace records");
        std::uint64_t key = 0;
        if (!parseIPv6(s + b, e - b, key)) fail("trace record is not a valid IPv6 address");
        keys.push_back(key);
    }
    return keys;
}

inline std::size_t lookupIndex(const std::vector<std::uint64_t>& keys, std::uint64_t k) {
    // Predecessor search: keys[0] == 0 guarantees a result.
    std::size_t lo = 0, hi = keys.size();   // invariant: keys[lo] <= k < keys[hi]
    while (lo + 1 < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (keys[mid] <= k) lo = mid;
        else hi = mid;
    }
    return lo;
}

void emitValue(OutBuffer& out, std::uint64_t value) {
    char line[32];
    char* p = line;
    if (value == kNoMatch) {
        *p++ = '-'; *p++ = '1'; *p++ = ' '; *p++ = '-'; *p++ = '1';
    } else {
        p = writeUnsigned(p, value >> 8);
        *p++ = ' ';
        p = writeUnsigned(p, value & 0xffu);
    }
    *p++ = '\n';
    out.push(line, static_cast<std::size_t>(p - line));
}

void runScalar(const Image& img, const std::vector<std::uint64_t>& keys, OutBuffer& out) {
    for (const std::uint64_t k : keys) emitValue(out, img.values[lookupIndex(img.keys, k)]);
}

void runBatch(const Image& img, const std::vector<std::uint64_t>& keys, std::size_t batch, OutBuffer& out) {
    const std::size_t n = keys.size();
    std::vector<std::pair<std::uint64_t, std::uint32_t>> order;
    std::vector<std::uint64_t> result;
    order.reserve(batch);
    result.resize(batch);
    for (std::size_t base = 0; base < n; base += batch) {
        const std::size_t cnt = std::min(batch, n - base);
        order.clear();
        for (std::size_t j = 0; j < cnt; ++j) order.emplace_back(keys[base + j], static_cast<std::uint32_t>(j));
        // Sorting the batch makes the predecessor searches share cache lines.
        std::sort(order.begin(), order.end());
        for (std::size_t j = 0; j < cnt; ++j)
            result[order[j].second] = img.values[lookupIndex(img.keys, order[j].first)];
        for (std::size_t j = 0; j < cnt; ++j) emitValue(out, result[j]);
    }
}

std::size_t parseBatchSize(const char* arg) {
    const std::size_t n = std::strlen(arg);
    if (n == 0) fail("batch size must be a nonempty decimal string");
    std::uint64_t v = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (!isDigitChar(arg[i])) fail("batch size must contain only ASCII decimal digits");
        if (v <= 256u) v = v * 10u + static_cast<std::uint64_t>(arg[i] - '0');
    }
    if (v < 1u || v > 256u) fail("batch size must be between 1 and 256");
    return static_cast<std::size_t>(v);
}

void cmdLookup(int argc, char** argv) {
    const std::string imagePath = argv[2];
    const std::string tracePath = argv[3];
    const std::string mode = argv[4];

    bool batchMode = false;
    std::size_t batch = 1;
    if (mode == "scalar") {
        if (argc != 5) fail("usage: planb64 lookup IMAGE TRACE scalar");
    } else if (mode == "batch") {
        if (argc != 6) fail("usage: planb64 lookup IMAGE TRACE batch BATCH_SIZE");
        batchMode = true;
        batch = parseBatchSize(argv[5]);
    } else {
        fail("unknown lookup mode (expected 'scalar' or 'batch')");
    }

    Image img = readImage(imagePath);
    std::vector<std::uint64_t> keys = readTrace(tracePath);

    OutBuffer out(stdout, kWriteChunk);
    if (batchMode) runBatch(img, keys, batch, out);
    else runScalar(img, keys, out);
    out.finish();
}

}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc >= 2 && std::strcmp(argv[1], "build") == 0) {
            if (argc != 4) fail("usage: planb64 build FIB IMAGE");
            cmdBuild(argv[2], argv[3]);
            return 0;
        }
        if (argc >= 2 && std::strcmp(argv[1], "lookup") == 0) {
            if (argc != 5 && argc != 6)
                fail("usage: planb64 lookup IMAGE TRACE {scalar|batch BATCH_SIZE}");
            cmdLookup(argc, argv);
            return 0;
        }
